  -- digital-literacy / Introduction to Digital Technology
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('a6a11261-1b9f-0555-6774-59a9ddece40e', 'digital-literacy', 'Introduction to Digital Technology', 'Devices, apps, and the information they handle.

You will learn to:
- Name common digital devices.
- Tell hardware and software apart.
- Explain what data is and where it is kept.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('66041078-e86b-1259-a3dd-17982a550f7f', 'a6a11261-1b9f-0555-6774-59a9ddece40e', 'Overview', 'article', 'Devices, apps, and the information they handle.

### Key terms
- **hardware**: The physical components of a computing device, such as the processor, memory, screen, and keyboard.
- **software**: Programs and instructions that tell hardware what to do.
- **application**: A software program designed to help a user perform a specific task.
- **data**: Information stored in a form a computer can process, such as text, numbers, images, or sound.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('7c11b1ea-18c7-fb2a-efbc-f4559cdaffdc', 'a6a11261-1b9f-0555-6774-59a9ddece40e', 'Explanation', 'article', 'Digital technology uses electronic devices to create, store, process, and share information. A device works when hardware, software, and data cooperate.

Hardware is the physical equipment. Software is the program code that tells the hardware what to do. An application is software built for a specific task, such as messaging or writing.

Data is the information software reads and writes. It can be stored on the device or in a remote service reached over the internet.', 1, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('7c11b1ea-18c7-fb2a-efbc-f4559cdaffdc', 'foundational', 'A digital device is a tool that works with information. Phones, computers, and tablets are digital devices.

Every device has two kinds of parts. Hardware is the part you can touch, such as the screen. Software is the set of instructions that runs inside, such as an app.

Data is the information a device keeps, such as photos, messages, and contacts.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('7c11b1ea-18c7-fb2a-efbc-f4559cdaffdc', 'advanced', 'Every digital system combines hardware, software, and data, and a fault in one layer can look like a fault in another. Understanding the layers helps you diagnose problems and judge tools.

Applications run on an operating system that manages hardware resources. Data can live locally or in a cloud service, which changes who can access it and whether it works offline.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('61f96111-2def-266d-4b2e-7ade9db7693b', 'a6a11261-1b9f-0555-6774-59a9ddece40e', 'Step by step', 'steps', 'Input | You tap, type, or speak to the device.
Software | An application interprets the request.
Hardware | Processor and memory carry out the work.
Data | Results are stored or shown on the screen.', 2, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('61f96111-2def-266d-4b2e-7ade9db7693b', 'foundational', 'Device | A phone, tablet, or computer.
Hardware | The parts you can touch: screen, battery, camera.
Software | Apps and instructions that make the hardware work.
Data | Photos, messages, and files that the device saves.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('61f96111-2def-266d-4b2e-7ade9db7693b', 'advanced', 'Hardware layer | Processor, memory, storage, sensors.
Operating system | Shares hardware among applications.
Application | Task-specific software that uses the system.
Data location | Local storage or cloud: affects access and privacy.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('60aad6e3-e310-835d-71f3-4bdc3a5ad96e', 'a6a11261-1b9f-0555-6774-59a9ddece40e', 'Example', 'article', 'When you send a voice note, the microphone (hardware) records sound, a messaging application (software) packages it, and the audio file (data) is stored and sent.', 3, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('60aad6e3-e310-835d-71f3-4bdc3a5ad96e', 'foundational', 'You take a photo. The camera and screen are hardware. The camera app is software. The saved picture is data.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('60aad6e3-e310-835d-71f3-4bdc3a5ad96e', 'advanced', 'A note-taking app that saves only on your phone keeps working offline but is lost if the phone breaks. A cloud-synced one survives a broken phone but needs internet to sync.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('7885ca4d-6121-87ef-3460-b9bdfd9dc53a', 'a6a11261-1b9f-0555-6774-59a9ddece40e', 'Practice', 'article', 'Pick a task you do on your phone. Describe which hardware, which application, and which data are involved.', 4, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('7885ca4d-6121-87ef-3460-b9bdfd9dc53a', 'foundational', 'Look at your phone. Write down two things you can touch (hardware), two apps you use (software), and two things it saves for you (data).');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('7885ca4d-6121-87ef-3460-b9bdfd9dc53a', 'advanced', 'Choose one app you use. Decide whether its data is stored locally, in the cloud, or both, and list one advantage and one risk of that choice.');
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('fd34f1cc-3e74-9533-fe26-e26528d7682b', 'a6a11261-1b9f-0555-6774-59a9ddece40e', 'Introduction to Digital Technology: check your understanding', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('65a91e60-7fc5-3890-a36a-41cbfba25eaf', 'fd34f1cc-3e74-9533-fe26-e26528d7682b', 'A camera on a phone is an example of which?', '["Software","Hardware","Data","A password"]'::jsonb, 1, 0, 0, 1, 'The camera is a physical component.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('3f4e1e5d-23af-57c9-a415-3c5671b848f4', 'fd34f1cc-3e74-9533-fe26-e26528d7682b', 'A saved photo is an example of which?', '["Data","Hardware","A network","A screen"]'::jsonb, 0, 1, 0, 1, 'A photo is information stored on the device.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('f76161b1-c548-5ffd-603b-4e5b3ae451e1', 'fd34f1cc-3e74-9533-fe26-e26528d7682b', 'Which pair correctly matches hardware and software?', '["Screen and battery","Keyboard and messaging app","Browser and calculator app","Photo and video"]'::jsonb, 1, 2, 0, 2, 'A keyboard is hardware and a messaging app is software.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('a187db8b-f7b8-7702-91ee-a609b206d823', 'fd34f1cc-3e74-9533-fe26-e26528d7682b', 'An application is best described as:', '["A physical part of a device","Software built for a specific task","A kind of cable","A secret code"]'::jsonb, 1, 3, 0, 2, 'Applications are task-specific software.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('401f9cef-043b-ad3a-d2de-26b6b54734dc', 'fd34f1cc-3e74-9533-fe26-e26528d7682b', 'A notes app saves only on your phone. What is a main risk?', '["Notes are lost if the phone is lost or broken","The app becomes hardware","Notes cannot be typed","The screen turns off"]'::jsonb, 0, 4, 0, 3, 'Local-only data has no backup copy elsewhere.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('47c24c1f-740a-ff75-4521-11c65ebb2d41', 'fd34f1cc-3e74-9533-fe26-e26528d7682b', 'Why can a cloud-synced app work on a new phone after login?', '["The data is stored on a remote server","The new phone is the same hardware","Software cannot move","Passwords are copied by Wi-Fi"]'::jsonb, 0, 5, 0, 3, 'Cloud data is kept on a server and linked to your account.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('cb438202-678e-4cc9-c6c9-fa32ac1d6d17', 'a6a11261-1b9f-0555-6774-59a9ddece40e', 'sort', 'Sort it out', 'Is each item hardware, software, or data? Tap an item, then tap its group.', '{"groups":["Hardware","Software","Data"],"items":[{"id":"a","label":"Phone screen","group":"Hardware"},{"id":"b","label":"Web browser","group":"Software"},{"id":"c","label":"Saved photo","group":"Data"},{"id":"d","label":"Battery","group":"Hardware"},{"id":"e","label":"Messaging app","group":"Software"},{"id":"f","label":"Contact list","group":"Data"},{"id":"g","label":"Camera","group":"Hardware"},{"id":"h","label":"Calculator app","group":"Software"},{"id":"i","label":"Text message","group":"Data"}]}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = 'a6a11261-1b9f-0555-6774-59a9ddece40e';

  -- digital-literacy / Internet and Online Safety
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('415db9be-f0bc-8694-008d-20a552e4ddfd', 'digital-literacy', 'Internet and Online Safety', 'Passwords, privacy, and safe browsing.

You will learn to:
- Explain what the internet is.
- Describe why strong, unique passwords and a second check protect accounts.
- Recognize what personal information should be kept private.', 1, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('ca6380ee-79fa-9d72-30d3-c263d00674f5', '415db9be-f0bc-8694-008d-20a552e4ddfd', 'Overview', 'article', 'Passwords, privacy, and safe browsing.

### Key terms
- **internet**: A global system of interconnected networks that exchange data using shared communication rules.
- **password**: A secret string of characters used to prove that you are allowed to access an account.
- **authentication**: The process of verifying a user identity before granting access.
- **two-factor authentication**: A login method that requires two different proofs of identity, such as a password and a one-time code.
- **privacy**: The ability to control what personal information is collected, shared, and who can see it.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('80632540-0748-4d19-5cb4-cdf049469ea8', '415db9be-f0bc-8694-008d-20a552e4ddfd', 'Explanation', 'article', 'The internet is a global network of networks that exchange data using shared rules. Anything you send can pass through many systems before it arrives.

Strong passwords are long and unique. Unique matters because attackers reuse stolen passwords on other sites. Two-factor authentication adds a second proof, such as a code sent to your phone, so a stolen password alone is not enough.

Privacy settings control which personal details are visible. Share the minimum needed.', 1, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('80632540-0748-4d19-5cb4-cdf049469ea8', 'foundational', 'The internet connects computers and phones all over the world so they can share information.

A password is a secret that proves an account is yours. Never share it, and use a different password for each account.

Privacy means you decide who can see your personal information, such as your address and phone number.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('80632540-0748-4d19-5cb4-cdf049469ea8', 'advanced', 'Account security rests on layers: a unique password limits the damage of a breach, two-factor authentication limits the damage of a stolen password, and encryption limits what an eavesdropper can read.

Privacy is also a trade-off. Services collect data in exchange for convenience, so evaluate what a service asks for compared with what it needs.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('79b89c29-ec87-ff4c-595e-6436f31c7cfd', '415db9be-f0bc-8694-008d-20a552e4ddfd', 'Step by step', 'steps', 'Create | Choose a long, unique password.
Add a second check | Turn on two-factor authentication.
Review privacy | Limit who sees your details.
Check the address | Confirm the website before logging in.', 2, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('79b89c29-ec87-ff4c-595e-6436f31c7cfd', 'foundational', 'Connect | Your device joins the internet.
Log in | You use a private password.
Protect | Share personal details only with people you trust.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('79b89c29-ec87-ff4c-595e-6436f31c7cfd', 'advanced', 'Threat | Identify what could go wrong: leak, guess, eavesdrop.
Control | Match a control: unique password, second factor, encryption.
Trade-off | Weigh convenience against exposure.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('038ff0e3-bb4e-f9d7-6789-a2813bb29c5d', '415db9be-f0bc-8694-008d-20a552e4ddfd', 'Example', 'article', 'A shop account is leaked. Because your email uses a different password and two-factor authentication, the attacker cannot get into your email.', 3, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('038ff0e3-bb4e-f9d7-6789-a2813bb29c5d', 'foundational', 'If you use one password everywhere and one website leaks it, a stranger can open all of your accounts. A different password for each account stops that.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('038ff0e3-bb4e-f9d7-6789-a2813bb29c5d', 'advanced', 'A flashlight app that asks for your contacts and location requests far more data than it needs. That mismatch is a warning sign.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('0f60e510-223c-63ec-e731-28c836d3f5db', '415db9be-f0bc-8694-008d-20a552e4ddfd', 'Practice', 'article', 'List three accounts you use. For each, say whether it has a unique password and whether two-factor authentication is available.', 4, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('0f60e510-223c-63ec-e731-28c836d3f5db', 'foundational', 'Make up a password phrase of four unrelated words. Do not use it anywhere real. Why is a phrase better than your name or birthday?');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('0f60e510-223c-63ec-e731-28c836d3f5db', 'advanced', 'Pick an app you use. List the permissions it requests, mark which are needed for its purpose, and decide which you would deny.');
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('3adfa707-a917-6d70-ab45-6cbed37d33ed', '415db9be-f0bc-8694-008d-20a552e4ddfd', 'Internet and Online Safety: check your understanding', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('79c86f98-710b-c2ed-cdeb-5836cc3d5adb', '3adfa707-a917-6d70-ab45-6cbed37d33ed', 'Which is the safest thing to do with your password?', '["Share it with a friend","Keep it private","Write it in a public chat","Use your name"]'::jsonb, 1, 0, 1, 1, 'A password is a secret and should stay private.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('afd9f060-f55c-7ca6-d6fc-6354a4c77e94', '3adfa707-a917-6d70-ab45-6cbed37d33ed', 'What does the internet do?', '["Connects devices around the world","Charges phones","Makes screens brighter","Stores only photos"]'::jsonb, 0, 1, 1, 1, 'The internet connects networks and devices.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('588c7360-84c8-cc1b-9667-adb7fc1a0548', '3adfa707-a917-6d70-ab45-6cbed37d33ed', 'Why is a long password with four unrelated words a good choice?', '["It is hard to guess","It is the same everywhere","It is short","It works without internet"]'::jsonb, 0, 2, 1, 2, 'Length and unpredictability make guessing harder.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('298723ae-153c-5453-5fa2-9d10b5e96ab6', '3adfa707-a917-6d70-ab45-6cbed37d33ed', 'What does two-factor authentication add?', '["A second proof of identity","Faster internet","More storage","A new keyboard"]'::jsonb, 0, 3, 1, 2, 'It requires something beyond the password.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('cb52fa8f-54bf-d49b-418e-ac7aa77a110b', '3adfa707-a917-6d70-ab45-6cbed37d33ed', 'A shop leaks your password, which you reused on email. What is the most likely result?', '["Nothing happens","An attacker may try it on your email account","Your phone updates","Your Wi-Fi slows"]'::jsonb, 1, 4, 1, 3, 'Attackers reuse leaked passwords on other sites.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('0a1f3160-3e7f-9907-3a47-3b05d86fe3d9', '3adfa707-a917-6d70-ab45-6cbed37d33ed', 'A flashlight app asks for contacts and location. What does this suggest?', '["It needs them to shine light","It requests more data than its purpose needs","It is safer","It is a browser"]'::jsonb, 1, 5, 1, 3, 'Permissions should match the purpose of the app.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('001c9819-ba44-964a-5d86-c3e411a9254a', '415db9be-f0bc-8694-008d-20a552e4ddfd', 'password', 'Build a strong password', 'Type a practice password and watch the checklist. It stays in this box: it is not saved or sent anywhere. Never test a real password.', '{}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = '415db9be-f0bc-8694-008d-20a552e4ddfd';

  -- digital-literacy / Identifying Phishing and Online Scams
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('de3978c8-f1d3-e721-592d-56b850b49a37', 'digital-literacy', 'Identifying Phishing and Online Scams', 'Spot suspicious messages and respond safely.

You will learn to:
- Define phishing and scams.
- Identify warning signs in a message or link.
- Choose a safe response and verify through an official channel.', 2, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('6f1d9178-7acf-7f79-608f-89189ffe60d6', 'de3978c8-f1d3-e721-592d-56b850b49a37', 'Overview', 'article', 'Spot suspicious messages and respond safely.

### Key terms
- **phishing**: A form of social engineering in which attackers impersonate a trusted party to steal information.
- **scam**: A deceptive scheme intended to obtain money, goods, or information through false claims.
- **link**: A clickable reference that opens another web page or file.
- **malware**: Malicious software designed to damage, disrupt, or gain unauthorized access to a system.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('1f13c2f5-1b6a-c60f-4aa3-424549fb9797', 'de3978c8-f1d3-e721-592d-56b850b49a37', 'Explanation', 'article', 'Phishing uses deceptive messages or websites to steal information. Scams more broadly use false promises, threats, or urgency to take money.

Check the sender, the wording, and the link destination. Urgent tone, requests for passwords or one-time codes, unexpected attachments, and web addresses that only look similar to the real one are common signs.

Verify unexpected requests through an official channel you find yourself, not through the message.', 1, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('1f13c2f5-1b6a-c60f-4aa3-424549fb9797', 'foundational', 'Phishing is a fake message that pretends to be from someone you trust, such as a bank, so you will give away secrets.

A scam is a trick to get your money or your information.

Warning signs: the message is urgent, asks for a password or code, or has a strange link. If you see them, do not tap the link.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('1f13c2f5-1b6a-c60f-4aa3-424549fb9797', 'advanced', 'Phishing is social engineering: it exploits trust, urgency, and fear rather than technical flaws. Attackers study targets and tailor messages, so familiar details do not prove authenticity.

Evaluate each signal independently: sender identity, link destination, requested action, and channel. When signals conflict, treat the message as untrusted and verify out of band.

If you act on a scam, change the affected password, enable two-factor authentication, and report the message.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('479c7e06-98a6-0f55-eb0c-1c8e9769cae3', 'de3978c8-f1d3-e721-592d-56b850b49a37', 'Step by step', 'steps', 'Inspect sender | Does the address match the real organization?
Inspect content | Urgency, threats, or too-good offers?
Inspect link | Does the address match the official site?
Verify | Contact the organization through an official channel.', 2, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('479c7e06-98a6-0f55-eb0c-1c8e9769cae3', 'foundational', 'Stop | Do not tap or reply right away.
Look | Is it urgent? Does it ask for secrets?
Verify | Open the real app or call the official number.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('479c7e06-98a6-0f55-eb0c-1c8e9769cae3', 'advanced', 'Assess signals | Sender, link, action, channel.
Resolve conflicts | Any mismatch means treat as untrusted.
Verify out of band | Use a separate, trusted channel.
Respond | Report, and secure the account if you acted.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('0baff33e-e14b-8886-5b50-e8c33cfb34eb', 'de3978c8-f1d3-e721-592d-56b850b49a37', 'Example', 'article', 'An email from "support@bank-secure-login.example" asks you to confirm your PIN. The real bank would never ask for a PIN by email, and the domain is not the bank domain.', 3, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('0baff33e-e14b-8886-5b50-e8c33cfb34eb', 'foundational', 'A text says: "Your account is blocked. Tap here to log in now." Instead of tapping, you open your bank app yourself and see there is no problem.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('0baff33e-e14b-8886-5b50-e8c33cfb34eb', 'advanced', 'A message quotes your real name and your school but asks you to log in through a shortened link. Knowing personal details does not prove it is genuine: the shortened link hides the destination.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('4cdb132f-4576-a6b8-578e-b43bf8399222', 'de3978c8-f1d3-e721-592d-56b850b49a37', 'Practice', 'article', 'Write three questions you would ask about any unexpected message before acting on it.', 4, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('4cdb132f-4576-a6b8-578e-b43bf8399222', 'foundational', 'A message says you won a phone but must pay a small fee. List two warning signs and say what you would do.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('4cdb132f-4576-a6b8-578e-b43bf8399222', 'advanced', 'Describe how you would respond if you entered your password on a fake page. List your first three actions in order.');
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('629f1db8-f238-9ce9-82df-6c082cd7993c', 'de3978c8-f1d3-e721-592d-56b850b49a37', 'Identifying Phishing and Online Scams: check your understanding', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('8aa29f41-89bb-5b2b-0c82-84ee8427c18d', '629f1db8-f238-9ce9-82df-6c082cd7993c', 'A message says "Act now or lose your account!" What should you do?', '["Tap the link","Stop and verify it another way","Reply with your password","Forward it"]'::jsonb, 1, 0, 3, 1, 'Urgency is a warning sign. Verify separately.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('b1c69087-952b-4cbc-16a8-b8af9f348b56', '629f1db8-f238-9ce9-82df-6c082cd7993c', 'What is phishing?', '["A fake message trying to steal your information","A way to charge a phone","A kind of keyboard","A video format"]'::jsonb, 0, 1, 3, 1, 'Phishing impersonates a trusted sender to steal information.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('1adecf1f-71c6-690e-a94b-2136a6ba919d', '629f1db8-f238-9ce9-82df-6c082cd7993c', 'Which is the best way to check a message that claims to be from your bank?', '["Tap the link in the message","Open the bank app yourself or call the official number","Reply asking if it is real","Wait a week"]'::jsonb, 1, 2, 3, 2, 'Use an official channel you find yourself.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('c9e12319-d051-6b3e-c824-cce10f52d6e4', '629f1db8-f238-9ce9-82df-6c082cd7993c', 'Which is a common warning sign in a link?', '["An address that only resembles the real one","A padlock on every page","A short message","A blue button"]'::jsonb, 0, 3, 3, 2, 'Lookalike addresses imitate real sites.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('808c5feb-ca28-c16a-513b-350f158cc963', '629f1db8-f238-9ce9-82df-6c082cd7993c', 'A message uses your real name and school but asks you to log in via a shortened link. What is the best conclusion?', '["It must be genuine because it knows you","Personal details do not prove it is genuine, so verify out of band","Ignore the link but share your code","Reply with a photo of your ID"]'::jsonb, 1, 4, 3, 3, 'Attackers can gather personal details.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('0b962d08-015a-a836-d99a-8cccb49f0c93', '629f1db8-f238-9ce9-82df-6c082cd7993c', 'You typed your password on a fake page. What should you do first?', '["Nothing","Change that password, enable two-factor authentication, and report it","Delete the browser","Wait for a reply"]'::jsonb, 1, 5, 3, 3, 'Secure the account and report the attempt.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('b574114a-fd09-96f5-9b26-7fd3505e3805', 'de3978c8-f1d3-e721-592d-56b850b49a37', 'spot', 'Spot the red flags', 'Tap every part of this message that looks suspicious, then press Check.', '{"segments":[{"id":"s1","text":"From: support@bank-secure-login.example","flag":true,"why":"The sender address is not the real bank domain."},{"id":"s2","text":"Dear customer,","flag":true,"why":"A generic greeting. A real bank uses your name."},{"id":"s3","text":"URGENT: your account will be closed in 1 hour!","flag":true,"why":"Urgency and threats are used to stop you thinking."},{"id":"s4","text":"Click here to verify: http://bank-login-verify.example/secure","flag":true,"why":"The link goes to a lookalike site, not the official one."},{"id":"s5","text":"Reply with your PIN and password to keep access.","flag":true,"why":"A real bank never asks for your PIN or password."},{"id":"s6","text":"Thank you for banking with us.","flag":false,"why":"A polite closing is not a warning sign on its own."}]}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = 'de3978c8-f1d3-e721-592d-56b850b49a37';

  -- digital-literacy / Digital Communication
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('a9a28f0a-680b-1a39-3f17-28034e387afc', 'digital-literacy', 'Digital Communication', 'Email, attachments, and respectful messages.

You will learn to:
- Write a clear email with a subject line.
- Attach and check files before sending.
- Choose a suitable channel and tone.', 3, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('70a1b952-afca-b699-17b5-26f490eb6574', 'a9a28f0a-680b-1a39-3f17-28034e387afc', 'Overview', 'article', 'Email, attachments, and respectful messages.

### Key terms
- **email**: A system for sending messages and files electronically between mailboxes over a network.
- **attachment**: A file sent together with an electronic message.
- **browser**: Software used to retrieve, display, and navigate web pages.
- **encryption**: Converting data into an unreadable form that only someone with the correct key can reverse.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('ca11e117-cc61-8e2c-70b9-85528d24e206', 'a9a28f0a-680b-1a39-3f17-28034e387afc', 'Explanation', 'article', 'Email supports messages and files between people. A good email has a specific subject, a short greeting, a clear request, and a polite closing.

Check recipients before sending, and open attachments only from senders you expect. Large files may need compression or a sharing link.

Pick the channel that suits the message: a quick chat for a simple question, email for formal or lasting records.', 1, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('ca11e117-cc61-8e2c-70b9-85528d24e206', 'foundational', 'Email is like a letter that travels over the internet. You write who it is for, what it is about, and your message.

The subject line says what the email is about. An attachment is a file sent with the email.

Before you press send, check the address of the person, your message, and the attachment.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('ca11e117-cc61-8e2c-70b9-85528d24e206', 'advanced', 'Choosing a channel is a decision about audience, sensitivity, and record keeping. Sensitive information such as identity numbers should not travel by ordinary email; use a service with encryption or deliver it in person.

Tone adds meaning that text lacks, so be concise and unambiguous. Reply-all and forwarded threads can expose information to people who should not see it.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('97d01b0d-5479-34d0-11dd-6e89a6143a5b', 'a9a28f0a-680b-1a39-3f17-28034e387afc', 'Step by step', 'steps', 'Choose channel | Chat for quick; email for formal.
Draft | Subject, greeting, request, closing.
Check | Recipient, tone, attachment.
Send and confirm | Confirm that it arrived if it matters.', 2, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('97d01b0d-5479-34d0-11dd-6e89a6143a5b', 'foundational', 'To | Type the correct address.
Subject | Say what the email is about.
Message | Be clear and polite.
Attach and send | Add the file, check it, then send.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('97d01b0d-5479-34d0-11dd-6e89a6143a5b', 'advanced', 'Audience | Who needs to read this?
Sensitivity | Is any information private?
Channel | Match the channel and protections.
Review | Check recipients and thread history.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('8b3af416-795e-070c-db0d-9bacb005a64b', 'a9a28f0a-680b-1a39-3f17-28034e387afc', 'Example', 'article', 'Sending an application: use the subject "Application: Digital Skills Course", state your request in two sentences, attach your document as a PDF, and confirm the recipient.', 3, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('8b3af416-795e-070c-db0d-9bacb005a64b', 'foundational', 'To send homework: write the teacher address, use the subject "Homework: Unit 2", write "Hello, my homework is attached. Thank you.", attach the file, and send.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('8b3af416-795e-070c-db0d-9bacb005a64b', 'advanced', 'Forwarding a long thread to a new contact may reveal earlier private messages. Copy only the part that is needed.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('447d6d19-9586-e90f-f7c9-45922f1fa6bd', 'a9a28f0a-680b-1a39-3f17-28034e387afc', 'Practice', 'article', 'Draft an email to apply for a course. Include a subject, a two-sentence request, and name the attachment.', 4, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('447d6d19-9586-e90f-f7c9-45922f1fa6bd', 'foundational', 'Write a short email to a teacher that asks for an extra day. Include a subject line and a greeting.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('447d6d19-9586-e90f-f7c9-45922f1fa6bd', 'advanced', 'You must send a document containing your identity number to an office. Compare two ways to send it and choose the safer one.');
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('7eaa6e41-44fb-539f-3620-c7a0aaa3f189', 'a9a28f0a-680b-1a39-3f17-28034e387afc', 'Digital Communication: check your understanding', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('b4b45647-137a-223c-029f-498b7f9b844b', '7eaa6e41-44fb-539f-3620-c7a0aaa3f189', 'What should an email subject line do?', '["Say what the email is about","Be left blank","Contain your password","Be very long"]'::jsonb, 0, 0, 2, 1, 'A subject summarizes the message topic.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('166824f2-4f24-4a23-502f-03b1a31f442d', '7eaa6e41-44fb-539f-3620-c7a0aaa3f189', 'Before sending an email with a file, you should:', '["Check the recipient and attachment","Delete the message","Add your password","Turn off Wi-Fi"]'::jsonb, 0, 1, 2, 1, 'Check the address and the file first.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('57e3c960-fa66-0f71-8a81-5f32b4b1ebdb', '7eaa6e41-44fb-539f-3620-c7a0aaa3f189', 'Which channel suits a quick question to a classmate?', '["A formal printed letter","A short chat message","An email with a long signature","A phone update"]'::jsonb, 1, 2, 2, 2, 'Chat suits quick informal questions.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('35078b35-f097-e0aa-ff46-52e9baf43ef9', '7eaa6e41-44fb-539f-3620-c7a0aaa3f189', 'You receive an unexpected attachment from an unknown sender. What is best?', '["Open it immediately","Do not open it and check with the sender another way","Forward it to everyone","Reply with your password"]'::jsonb, 1, 3, 2, 2, 'Unexpected attachments can contain malware.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('12ff9c97-e0f4-2841-ef16-35224aab15ba', '7eaa6e41-44fb-539f-3620-c7a0aaa3f189', 'You must send your identity number to an office. What is the safest choice?', '["Ordinary email to many people","A protected or in-person method the office approves","A public post","A chat group"]'::jsonb, 1, 4, 2, 3, 'Sensitive data needs a protected channel.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('563c86d7-0078-bd1e-571a-29fb78dbd612', '7eaa6e41-44fb-539f-3620-c7a0aaa3f189', 'Why can forwarding a long email thread be risky?', '["It may reveal earlier private messages","It deletes the attachments","It slows the internet","It changes the subject"]'::jsonb, 0, 5, 2, 3, 'Threads often include earlier content others should not see.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('27dfd825-a0ed-c523-7e8f-1cb6c04a1ac8', 'a9a28f0a-680b-1a39-3f17-28034e387afc', 'order', 'Send an email in the right order', 'Use the arrows to put these steps in the correct order, then press Check.', '{"steps":["Press Send","Write a clear subject line","Open a new message","Attach the file","Type the recipient address","Write a short, polite message","Check the recipient and the attachment"],"answer":["Open a new message","Type the recipient address","Write a clear subject line","Write a short, polite message","Attach the file","Check the recipient and the attachment","Press Send"]}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = 'a9a28f0a-680b-1a39-3f17-28034e387afc';

  -- digital-literacy / Basic Digital Problem-Solving
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('2d1c17c4-159a-e900-fa8c-e867c1d0f6ce', 'digital-literacy', 'Basic Digital Problem-Solving', 'Troubleshooting everyday technology.

You will learn to:
- Describe a step-by-step troubleshooting method.
- Test one change at a time.
- Know when to update, restart, or ask for help.', 4, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('ee03b9c4-b145-66c5-bb1d-92ae159c1d0c', '2d1c17c4-159a-e900-fa8c-e867c1d0f6ce', 'Overview', 'article', 'Troubleshooting everyday technology.

### Key terms
- **troubleshooting**: A systematic process of identifying the cause of a problem and testing fixes.
- **network**: A group of connected devices that can exchange data.
- **update**: A new version of software that adds features or fixes errors and security flaws.
- **browser**: Software used to retrieve, display, and navigate web pages.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('165792bf-60ba-70f2-27e0-2e9781f24dac', '2d1c17c4-159a-e900-fa8c-e867c1d0f6ce', 'Explanation', 'article', 'Troubleshooting is a method: describe the problem, list likely causes, test the simplest cause first, and check whether the fix worked.

Change one thing at a time. If you change several at once, you cannot tell which one solved the problem.

Keeping software updated fixes many errors and security gaps. Write down what you tried so you can explain it if you need help.', 1, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('165792bf-60ba-70f2-27e0-2e9781f24dac', 'foundational', 'Troubleshooting means finding out why something is not working and fixing it.

Start with the easy steps: check that the device is on, charged, and connected. Try one fix at a time and see if it helped.

If nothing works, ask someone you trust or contact support.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('165792bf-60ba-70f2-27e0-2e9781f24dac', 'advanced', 'Systematic diagnosis treats a problem as a set of hypotheses. Observe the symptom, isolate variables by changing one at a time, and record each result.

Narrow the problem by comparison: does it fail on another network, another device, or another account? The comparison that changes the outcome points to the cause.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('5aaf381d-6212-e305-e950-063cbcb82f87', '2d1c17c4-159a-e900-fa8c-e867c1d0f6ce', 'Step by step', 'steps', 'Describe | What happens and when?
List causes | Connection, app, device, or account.
Test one cause | Simplest and reversible first.
Verify | Confirm it works, and note what fixed it.', 2, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('5aaf381d-6212-e305-e950-063cbcb82f87', 'foundational', 'Notice | What exactly is wrong?
Check basics | Power, battery, Wi-Fi.
Try one fix | For example, restart.
Check result | Did it work? If not, try the next one.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('5aaf381d-6212-e305-e950-063cbcb82f87', 'advanced', 'Observe | Record exact symptoms and error messages.
Hypothesize | Rank likely causes.
Isolate | Change one variable; compare devices or networks.
Document | Record what worked so you can repeat it.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('eebb6bd0-a23c-04ac-03b7-0f1063e81f0e', '2d1c17c4-159a-e900-fa8c-e867c1d0f6ce', 'Example', 'article', 'A page fails on your phone. Other sites work, so the network is fine. You clear the browser data for that site and reload: it works. The cause was the stored site data.', 3, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('eebb6bd0-a23c-04ac-03b7-0f1063e81f0e', 'foundational', 'A web page will not open. First check that Wi-Fi is on, then try another website, then restart the browser.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('eebb6bd0-a23c-04ac-03b7-0f1063e81f0e', 'advanced', 'A video call fails on home Wi-Fi but works on mobile data. The device and app are fine; the fault is in the home network, so test the router.');
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('7a2a73aa-0540-17e5-d570-f4eb6f03428f', '2d1c17c4-159a-e900-fa8c-e867c1d0f6ce', 'Practice', 'article', 'An app keeps closing. List three possible causes and the order you would test them, with a reason.', 4, false);
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('7a2a73aa-0540-17e5-d570-f4eb6f03428f', 'foundational', 'Your phone will not connect to Wi-Fi. List three easy steps you would try, in order.');
  insert into public.learning_unit_variants (unit_id, level_id, content) values ('7a2a73aa-0540-17e5-d570-f4eb6f03428f', 'advanced', 'A shared document will not save. Design three tests that separate a network problem, an account problem, and an app problem.');
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('1eb95ddb-8417-31b2-b591-0548eba09848', '2d1c17c4-159a-e900-fa8c-e867c1d0f6ce', 'Basic Digital Problem-Solving: check your understanding', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('afe7919a-b632-f848-45a3-9d1512a171ed', '1eb95ddb-8417-31b2-b591-0548eba09848', 'Your phone cannot open websites. What is an easy first check?', '["Whether Wi-Fi or mobile data is on","Delete all apps","Share your password","Buy a new phone"]'::jsonb, 0, 0, 2, 1, 'Check the simple basics first.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('1e90784d-ea11-6f54-94b5-2d01a7970880', '1eb95ddb-8417-31b2-b591-0548eba09848', 'What does troubleshooting mean?', '["Finding why something fails and fixing it","Buying new devices","Deleting messages","Choosing a password"]'::jsonb, 0, 1, 2, 1, 'It is the process of diagnosing and fixing problems.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('c7f405ce-f648-0925-7aa7-6c43b5bcadbd', '1eb95ddb-8417-31b2-b591-0548eba09848', 'Why should you try one fix at a time?', '["To know which fix worked","To waste time","To hide errors","To use more data"]'::jsonb, 0, 2, 2, 2, 'One change at a time reveals the cause.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('de16ef90-7183-6827-3a11-53ca12402a64', '1eb95ddb-8417-31b2-b591-0548eba09848', 'Why are software updates useful?', '["They often fix errors and security gaps","They remove the screen","They make passwords public","They always delete data"]'::jsonb, 0, 3, 2, 2, 'Updates patch faults and vulnerabilities.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('02bcd62f-e7bb-994d-75a2-4891005f0cc3', '1eb95ddb-8417-31b2-b591-0548eba09848', 'A video call fails on home Wi-Fi but works on mobile data. What does this suggest?', '["The problem is likely in the home network","The app has been deleted","The phone has no screen","Mobile data is broken"]'::jsonb, 0, 4, 2, 3, 'The change that fixed the symptom points to the home network.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('aba79823-2d64-6094-7455-8076df7dfe41', '1eb95ddb-8417-31b2-b591-0548eba09848', 'A document will not save. Which test best separates an account problem from a network problem?', '["Try saving on a different network and also sign in on another device","Reinstall everything immediately","Change five settings at once","Ignore the error"]'::jsonb, 0, 5, 2, 3, 'Comparing across networks and devices isolates variables.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('30eebf04-3e44-ba42-2060-40edcd622399', '2d1c17c4-159a-e900-fa8c-e867c1d0f6ce', 'order', 'Fix it step by step', 'A web page will not load. Put the troubleshooting steps in the best order, then press Check.', '{"steps":["Check whether it worked","Try one simple fix, such as reloading or restarting","If it still fails, try the next fix or ask for help","Check the basics: power, Wi-Fi or mobile data","Notice and describe exactly what is wrong"],"answer":["Notice and describe exactly what is wrong","Check the basics: power, Wi-Fi or mobile data","Try one simple fix, such as reloading or restarting","Check whether it worked","If it still fails, try the next fix or ask for help"]}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = '2d1c17c4-159a-e900-fa8c-e867c1d0f6ce';

  -- networking-basics / Introduction to Computer Networks
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('7cda96d3-ce70-df89-cca9-80a3a68d0443', 'networking-basics', 'Introduction to Computer Networks', 'What is a network? Devices that share information, LAN, WAN and the internet.

You will learn to:
- Explain how connected devices share information and resources.
- Tell a LAN from a WAN.
- Explain that the internet is a network of networks, not the same thing as home Wi-Fi.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('04866877-e5dd-a582-9910-e817033ebd7e', '7cda96d3-ce70-df89-cca9-80a3a68d0443', 'Network foundations', 'article', 'A **computer network** connects two or more devices using wired or wireless links so they can exchange data or share resources. Phones, laptops, printers and servers can all be networked.

A connection can exist without internet access. Two laptops can exchange files on a local network even if the outside internet is unavailable.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('809de810-38d1-aefb-6279-f4c000671119', '7cda96d3-ce70-df89-cca9-80a3a68d0443', 'Local and wide-area networks', 'article', 'A **local area network (LAN)** connects devices over a limited area such as a home, classroom or office.

A **wide area network (WAN)** spans larger distances and can connect multiple LANs.

The **internet** is a global network of interconnected networks. It is not the same thing as a single home Wi-Fi network.', 1, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('52dfc909-7dd7-38e4-82a5-2431c6ae28b7', '7cda96d3-ce70-df89-cca9-80a3a68d0443', 'Everyday examples', 'article', '- At home, a phone sends a print job to a wireless printer over the LAN.
- At school, computers share a file server.
- A web browser reaches a website across the internet.
- **Wi-Fi** describes a wireless network link. It does not by itself guarantee internet access.', 2, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('c023e201-8924-71bd-2bc1-dd828b70b890', '7cda96d3-ce70-df89-cca9-80a3a68d0443', 'Visual steps', 'steps', 'Phone and laptop | Devices in the home send data to the home router.
Home Wi-Fi router | Joins the devices together. This home side is the LAN.
Printer | Connected on the home side, so it can be used without the internet.
Connection beyond the router | The link to the provider. This is the WAN and the internet.
Reading order | Phone and laptop, then router, then the internet. The printer stays on the LAN side.', 3, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('4d97586a-045a-2517-5ecf-ea65a17d00fa', '7cda96d3-ce70-df89-cca9-80a3a68d0443', 'Example and practice', 'article', '### Example
A family prints a school form from a phone while the internet is down. The print job works because the phone and printer share the home LAN. Opening an online article still fails until the internet connection returns.

### Practice
Decide which activities need only a LAN (for example, printing to a home printer) and which need the internet (for example, opening a remote website). Explain why.', 4, false);
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('ce247fd6-8d77-f505-23ad-af2d0b65778c', '7cda96d3-ce70-df89-cca9-80a3a68d0443', 'Introduction to Computer Networks: module quiz', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('94922881-da8a-acc4-c2fe-02de90c05bdb', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'What is a computer network?', '["A set of connected devices that exchange data","A computer with extra storage","Only a website","A single disconnected phone"]'::jsonb, 0, 0, 0, 1, 'A network allows connected devices to exchange data and share resources.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('fae9476a-4a84-c994-8b42-b6d50fe4318a', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'What does LAN stand for?', '["Large Access Node","Local Area Network","Linked Application Network","Long Area Navigation"]'::jsonb, 1, 1, 0, 1, 'LAN means Local Area Network.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('2ed0a736-8f88-fb00-e2cc-531f998175ab', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'Which example is typically a WAN?', '["Devices in one classroom","Keyboard attached to a laptop","Network connecting offices in different cities","A printer connected by USB only"]'::jsonb, 2, 2, 0, 1, 'A WAN connects networks across broader geographic areas.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('e7192745-89bf-5480-a87f-2d6a77441762', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'Why can a printer work on a LAN without internet?', '["Printers always contain mobile data","The internet is stored in the printer","Wi-Fi automatically creates an internet service","A LAN can carry local traffic independently"]'::jsonb, 3, 3, 1, 2, 'Local devices can communicate without a connection to the global internet.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('84078b30-7472-b02c-3f46-f1ca7296d530', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'How does the internet differ from a LAN?', '["The internet interconnects many networks globally","The internet is a single computer","A LAN always uses cables","A LAN cannot transfer files"]'::jsonb, 0, 4, 1, 2, 'The internet connects many separate networks; a LAN covers a limited area.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('15c2275e-6ba1-3dc8-142e-21f902d951cb', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'Why can a phone show Wi-Fi connected but a website fail?', '["Wi-Fi and internet are identical","Wi-Fi may connect locally while internet access is down","The phone has no screen","All websites require Ethernet"]'::jsonb, 1, 5, 1, 2, 'Wi-Fi connectivity does not guarantee an upstream internet connection.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('46c03b96-484d-ec6a-7062-348bcc2a271a', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'Two laptops need to exchange a file in the same room without internet. What is suitable?', '["Wait until a search engine loads","Buy a domain name","Use a local network or direct local sharing","Use only a WAN subscription"]'::jsonb, 2, 6, 2, 2, 'Local file sharing can operate without internet.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('5d0642a2-64bf-a974-1d05-7139553e5cef', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'A school wants computers in one lab to share a printer. Which network fits?', '["WAN across provinces","Satellite-only global network","No network at all","LAN in the computer lab"]'::jsonb, 3, 7, 2, 2, 'A LAN is appropriate for a limited location.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('2c0b8d20-5075-1584-e68a-1e7238f2e87f', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'A learner needs to open an online article hosted abroad. What is generally required?', '["An internet connection","Only a powered printer","Only Bluetooth headphones","A USB mouse"]'::jsonb, 0, 8, 2, 2, 'Accessing a remote public website generally requires internet connectivity.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('cb5025bf-2fb1-f7fc-60c9-4ba55a56c457', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'An office has a functioning LAN, but external websites fail on every computer. Which explanation is most plausible?', '["All local network links must be broken","The upstream internet connection or gateway may be unavailable","Every computer is infected","The office has too many printers"]'::jsonb, 1, 9, 3, 3, 'The LAN may still work while its internet connection fails.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('8e904eb5-fe03-33d4-39f1-5ef6f895af09', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'Which setup best supports local file sharing during an internet outage?', '["Devices depending exclusively on a cloud-only server","Devices with networking disabled","Devices on the same working LAN with a local file server","Devices with no local storage or connection"]'::jsonb, 2, 10, 3, 3, 'A local server and LAN can remain available during an outside outage.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('cb1cfe1c-ebfd-38d1-e4c2-43d8b9b10998', 'ce247fd6-8d77-f505-23ad-af2d0b65778c', 'A team calls its classroom Wi-Fi "the entire internet." What correction is best?', '["Wi-Fi can never connect to the internet","A classroom LAN is always a WAN","Every Wi-Fi signal is a different website","Wi-Fi is a wireless way to connect locally; the internet is the larger network of networks"]'::jsonb, 3, 11, 3, 3, 'Wi-Fi is an access technology, not a synonym for the internet.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('cf58c148-a9d9-7922-e467-665f172521f2', '7cda96d3-ce70-df89-cca9-80a3a68d0443', 'sort', 'LAN only or needs the internet?', 'Does each activity need only a LAN, or does it need the internet? Tap an item, then tap its group.', '{"groups":["LAN only","Needs internet"],"items":[{"id":"a","label":"Printing to a home Wi-Fi printer","group":"LAN only"},{"id":"b","label":"Opening a website hosted in another country","group":"Needs internet"},{"id":"c","label":"Sharing a file between two laptops in the same room","group":"LAN only"},{"id":"d","label":"Watching a video from an online service","group":"Needs internet"},{"id":"e","label":"Using a school file server from a lab computer","group":"LAN only"},{"id":"f","label":"Sending an email to a friend in another city","group":"Needs internet"}]}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = '7cda96d3-ce70-df89-cca9-80a3a68d0443';

  -- networking-basics / Networking Devices and Connections
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('839a7f34-b206-4cfb-bc31-1ef9e1c30c52', 'networking-basics', 'Networking Devices and Connections', 'How do devices connect? Routers, switches, modems, access points, Ethernet and Wi-Fi.

You will learn to:
- Identify common network hardware.
- Tell wired links from wireless links.
- Choose basic equipment for a simple network.', 1, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('a6e71377-8697-f0d0-3b60-a0285761466a', '839a7f34-b206-4cfb-bc31-1ef9e1c30c52', 'Routers and switches', 'article', 'A **router** forwards traffic between different networks, such as a home LAN and an internet provider network.

A **switch** connects multiple wired devices within a LAN and sends data toward the correct local port.

Some home routers include a built-in switch and Wi-Fi access point.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('f553a904-f64c-3eb8-4a1d-a7cdb80a3679', '839a7f34-b206-4cfb-bc31-1ef9e1c30c52', 'Modems, access points, and links', 'article', 'A **modem** or provider gateway connects a subscriber to the provider''s access technology when that connection requires one.

A wireless **access point** lets compatible devices join a LAN through Wi-Fi.

**Ethernet** cables commonly link fixed devices to a switch or router. Wi-Fi offers mobility but can be affected by distance, interference and obstacles.', 1, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('31f8df73-e600-1749-e979-270c12de6669', '839a7f34-b206-4cfb-bc31-1ef9e1c30c52', 'Choosing connections', 'article', '- A fixed desktop that needs stable connectivity may benefit from Ethernet.
- A mobile phone typically uses Wi-Fi.
- Internet access depends on a working route through local networking equipment and the service provider.
- Different homes may have one combined gateway instead of separate devices.', 2, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('46a05825-298e-891e-fa77-010b4dddeafe', '839a7f34-b206-4cfb-bc31-1ef9e1c30c52', 'Visual steps', 'steps', 'Desktop | Connects with an Ethernet cable to a switch.
Switch | Links wired devices on the LAN, then connects to the router or gateway.
Router or gateway | Forwards traffic to the internet provider (ISP).
Phone | Connects by Wi-Fi to the access point or router.
Combined box | One device may do the router, switch and access point jobs together.', 3, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('f90a1fd1-3e75-bfcb-ccaf-4a2af9365d98', '839a7f34-b206-4cfb-bc31-1ef9e1c30c52', 'Example and practice', 'article', '### Example
A small classroom has six wired desktop computers and several tablets. The desktops plug into a switch by Ethernet for a stable link. The tablets use Wi-Fi from an access point. Both groups join the same LAN through one router.

### Practice
A classroom has six wired desktop computers and mobile tablets. Select equipment that can connect both sets to one LAN and explain the trade-offs.', 4, false);
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('9d0c42ad-feba-d6ac-0d60-1304a9db84c0', '839a7f34-b206-4cfb-bc31-1ef9e1c30c52', 'Networking Devices and Connections: module quiz', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('d2023224-9eeb-e88c-4e5d-20acfb44c403', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'Which device primarily forwards packets between networks?', '["Router","Switch","Monitor","Keyboard"]'::jsonb, 0, 0, 0, 1, 'A router connects and forwards traffic between different networks.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('fd4b247f-8edd-c18d-bb85-b393a2e37520', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'What is the main job of an Ethernet switch?', '["Provide a video display","Connect wired devices within a LAN","Write Wi-Fi passwords","Translate websites into books"]'::jsonb, 1, 1, 0, 1, 'A switch interconnects wired devices on a local network.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('d19bb211-688f-0075-88ec-f566559cf0ae', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'Which medium usually provides a wired LAN connection?', '["Bluetooth speaker","Printed barcode","Ethernet cable","Camera lens"]'::jsonb, 2, 2, 0, 1, 'Ethernet cabling is a common wired LAN connection method.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('639d26ea-b496-bd96-7613-4a7300d07053', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'Why might a classroom use a switch as well as a router?', '["Both devices do exactly the same job in every case","The switch replaces every computer","A router can never connect to a switch","The switch connects local wired devices; the router connects networks"]'::jsonb, 3, 3, 1, 2, 'Switches serve local wired connectivity; routers provide network-to-network forwarding.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('ee76c146-ac70-6291-13d6-ab7e6e57968f', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'Why can Wi-Fi become unreliable through several thick walls?', '["Wireless signals can weaken and encounter interference","Ethernet cables disappear","Wi-Fi becomes a WAN automatically","The router loses its IP permanently"]'::jsonb, 0, 4, 1, 2, 'Distance and barriers can reduce wireless signal quality.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('2c570dbd-029e-30d0-03d1-863f1104da99', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'How can one home gateway serve as a router, switch, and access point?', '["Every home contains three hidden computers","It can combine several networking functions in one device","Switching is impossible on routers","It uses no network interfaces"]'::jsonb, 1, 5, 1, 2, 'Consumer gateways frequently integrate several networking functions.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('2b71a79d-fb57-8cf4-e006-7e44a315293b', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'A desktop has an Ethernet port and sits beside a switch. Which connection is sensible?', '["HDMI cable to the internet provider","USB charger to the wall","Ethernet cable from desktop to switch","Audio cable to the router"]'::jsonb, 2, 6, 2, 2, 'An Ethernet cable carries wired network traffic.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('d3577cb1-cff6-df0c-485a-f0ded90300cb', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'A phone needs wireless access to a school LAN. Which component provides the wireless entry point?', '["Printer toner","Ethernet-only patch cable","Monitor","Wireless access point"]'::jsonb, 3, 7, 2, 2, 'An access point lets wireless devices join the LAN.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('3fd030f2-17cc-e186-0910-3e0d3b625177', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'A house loses power to its Wi-Fi router. What is the first sensible action?', '["Check that the router has power and restart only when appropriate","Change every website password","Replace all phones","Reinstall every web browser"]'::jsonb, 0, 8, 2, 2, 'Start by verifying the affected equipment is powered and functioning.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('27b47e27-0172-d951-4479-f1de0a12507d', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'Wired computers work, but tablets cannot join Wi-Fi. Where should you investigate first?', '["Every Ethernet cable must be broken","Wireless access point or Wi-Fi settings","The printer tray","The keyboard layout"]'::jsonb, 1, 9, 3, 3, 'A wireless-specific fault is more likely when wired access still works.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('1a493f0a-ed07-bbbb-f3df-5f1f726ac27e', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'An Ethernet PC shows no link light while nearby PCs work. What is the best initial check?', '["Assume the entire internet is offline","Delete the operating system","Check that its cable is firmly connected and try a known-good port or cable","Change the website URL"]'::jsonb, 2, 10, 3, 3, 'A single failed wired link suggests checking its local cable or port.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('197c3549-588e-a6e6-c346-728f9b264786', '9d0c42ad-feba-d6ac-0d60-1304a9db84c0', 'A team needs reliable connectivity for fixed desktop PCs and mobility for tablets. What is the best design?', '["Wi-Fi only for every device without exception","No router and no access point","Separate internet subscription per tablet","Ethernet for desktops and Wi-Fi for tablets on the same LAN"]'::jsonb, 3, 11, 3, 3, 'A combined wired and wireless LAN matches the different device needs.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('29442ff7-c9e7-ec7f-0654-371314190f16', '839a7f34-b206-4cfb-bc31-1ef9e1c30c52', 'sort', 'Wired or wireless?', 'A classroom has fixed desktops and mobile tablets. Which link suits each device? Tap an item, then tap its group.', '{"groups":["Ethernet (wired)","Wi-Fi (wireless)"],"items":[{"id":"a","label":"A desktop fixed to a desk that needs a stable link","group":"Ethernet (wired)"},{"id":"b","label":"A tablet carried between rooms","group":"Wi-Fi (wireless)"},{"id":"c","label":"A computer plugged into a switch beside it","group":"Ethernet (wired)"},{"id":"d","label":"A phone used around the school","group":"Wi-Fi (wireless)"},{"id":"e","label":"A lab desktop used for long file transfers","group":"Ethernet (wired)"},{"id":"f","label":"A laptop moved to the library","group":"Wi-Fi (wireless)"}]}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = '839a7f34-b206-4cfb-bc31-1ef9e1c30c52';

  -- networking-basics / IP Addresses and Internet Communication
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('be37cb16-5207-bcd7-651d-10c4bb08003c', 'networking-basics', 'IP Addresses and Internet Communication', 'How does information reach the right device? IP addresses, DNS, packets and website requests.

You will learn to:
- Describe what an IP address is for.
- Explain what DNS does.
- Explain what a packet is.
- Describe the simplified steps for opening a website.', 2, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('8ec88bc5-44a6-5abc-14f8-ca10526b4f8f', 'be37cb16-5207-bcd7-651d-10c4bb08003c', 'IP addresses', 'article', 'An **Internet Protocol (IP) address** identifies a network interface for communication. IPv4 addresses are often written as four decimal numbers separated by dots, such as 192.168.1.10.

Private addresses can be used inside a LAN. A public-facing address is used for communication across the wider internet, often with network address translation in home networks.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('174c743d-8c61-5116-d144-75cb36878fda', 'be37cb16-5207-bcd7-651d-10c4bb08003c', 'DNS and names', 'article', 'The **Domain Name System (DNS)** helps a device find an IP address associated with a domain name, such as example.com.

DNS does not itself load a web page. It supplies information used to reach the destination. A name lookup problem can stop a website opening by name even when the network is connected.', 1, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('3d745d56-7ab6-7e71-38c5-601e08ffa34c', 'be37cb16-5207-bcd7-651d-10c4bb08003c', 'Packets and website requests', 'article', 'Large messages are split into manageable units called **packets**. The network directs packets toward the destination.

In a simplified webpage visit:
- Enter the domain name.
- Resolve the name using DNS.
- Connect to the server.
- Request and receive the page content.

Modern browsing may also use encrypted **HTTPS** connections.', 2, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('3c9080aa-2e2d-22dc-dff6-08534417acb6', 'be37cb16-5207-bcd7-651d-10c4bb08003c', 'Visual steps', 'steps', 'Learner types example.com | The browser starts with a name that people can remember.
DNS resolves the name | DNS supplies the IP address for that name.
Packets route to the web server | Data travels in packets toward the server.
Webpage appears | The page content comes back and your browser shows it.
Simplified model | Real connections have more steps, but this order is a good start.', 3, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('8a123a76-dd01-71cd-7fe8-9eade183b142', 'be37cb16-5207-bcd7-651d-10c4bb08003c', 'Example and practice', 'article', '### Example
You type a school website name. DNS finds its IP address. Your browser connects to the server, requests the page, and receives it in packets. The page then appears on your screen.

### Practice
Explain why opening a site by a known IP address might work when its domain name fails, and why that result alone does not guarantee every site supports direct-IP browsing.', 4, false);
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('d5493d20-88c2-bbae-f157-22c2ef967f5c', 'be37cb16-5207-bcd7-651d-10c4bb08003c', 'IP Addresses and Internet Communication: module quiz', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('11afe97e-bcc5-2767-8255-8c153b778e4b', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'What does IP stand for in IP address?', '["Internet Protocol","Internal Printer","Internet Program","Input Port"]'::jsonb, 0, 0, 0, 1, 'IP is short for Internet Protocol.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('2ff400ac-185b-b31e-b58c-b16227b11ca6', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'What does DNS commonly help a device find?', '["The monitor brightness","An IP address associated with a domain name","A Wi-Fi password","An Ethernet cable color"]'::jsonb, 1, 1, 0, 1, 'DNS resolves names to records such as IP addresses.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('f9bbc10b-ad44-b29a-ed00-a745ca435dec', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'What is a packet in networking?', '["A type of printer paper","A Wi-Fi password","A unit of data sent across a network","A physical router"]'::jsonb, 2, 2, 0, 1, 'Packets are units used to carry data over networks.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('41a4a652-560d-5a00-7adb-32d6cfd4cf42', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'Why use domain names rather than require people to memorize numeric addresses?', '["Names eliminate the need for network addresses","DNS turns a computer into a router","Domains automatically prevent phishing","Names are easier for people to remember, and DNS helps locate destinations"]'::jsonb, 3, 3, 1, 2, 'DNS makes human-readable names usable for reaching services.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('21ce91b4-fae1-3a73-3621-afc15fc53aaa', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'What is the role of IP addressing when data travels?', '["It helps network equipment direct data toward an intended destination","It changes every document into a photo","It supplies electricity to Wi-Fi","It replaces all application protocols"]'::jsonb, 0, 4, 1, 2, 'IP addresses help identify destinations for routed traffic.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('c7dcb35d-ff44-7d1e-c093-417b41ac3c10', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'Why is opening a webpage more than simply "using DNS"?', '["DNS already contains all web pages","DNS assists name resolution; connections and data transfers are still required","No packets are used on the internet","The keyboard sends the whole page"]'::jsonb, 1, 5, 1, 2, 'Resolving the domain is only one stage in accessing a website.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('945b06c0-f5cc-588f-68cd-f317d47ab8a7', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'A learner sees 192.168.1.25 in device settings. What is it likely to represent?', '["A domain name","A Wi-Fi password","A private IPv4 address","An Ethernet cable model"]'::jsonb, 2, 6, 2, 2, '192.168.x.x is within a commonly used private IPv4 range.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('306bdccd-988b-7ee5-eaf2-f79848e64970', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'A site is entered as example.com. Which service is normally consulted to learn its address?', '["Bluetooth pairing service","Print spooler","Screen saver","DNS resolver"]'::jsonb, 3, 7, 2, 2, 'DNS is used for domain-name resolution.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('585b9f6a-d9ad-08dc-c5e9-de6e51380d3e', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'Which sequence best describes simplified website access?', '["Resolve name, connect to server, request content, receive content","Print page, then enable cable, then invent a domain","Request content without any network, then resolve name","Change password, then power off router"]'::jsonb, 0, 8, 2, 2, 'A web request generally uses name resolution and network communication.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('647a9947-3dd7-92f4-30d6-4d51347af371', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'A browser says a domain cannot be resolved, but other network checks succeed. What should you test?', '["Only the monitor cable","DNS settings and resolver availability","Printer ink level","Mouse battery"]'::jsonb, 1, 9, 3, 3, 'A name resolution error points toward DNS-related checks.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('ec5b91b9-a3fa-7120-cee4-cfeb267254b9', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'A device has a private IP but no working default gateway for reaching outside networks. What is the likely impact?', '["All local printers must automatically fail","Its keyboard becomes disabled","Local LAN traffic may work while internet destinations fail","DNS names disappear from the web"]'::jsonb, 2, 10, 3, 3, 'A gateway is needed for forwarding traffic beyond the local network.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('d470961b-dc2c-0658-20ba-fde2a7e676e9', 'd5493d20-88c2-bbae-f157-22c2ef967f5c', 'A learner claims an IP address always identifies a particular person. Which response is best?', '["IP addresses are legal names","All phones share one permanent public IP","IP addresses cannot change","An IP address identifies network connectivity and is not, by itself, proof of a specific person"]'::jsonb, 3, 11, 3, 3, 'Addresses identify network endpoints or interfaces, not reliably individual people.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('316fa7e3-9e6f-daea-66b4-396c6fc2eacf', 'be37cb16-5207-bcd7-651d-10c4bb08003c', 'order', 'Open a website, step by step', 'Use the arrows to put the steps in the order they happen, then press Check.', '{"steps":["Your device puts the packets back together and shows the page","DNS looks up the IP address","You type a website name","The server sends the page back as packets","Your browser sends a request in packets"],"answer":["You type a website name","DNS looks up the IP address","Your browser sends a request in packets","The server sends the page back as packets","Your device puts the packets back together and shows the page"]}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = 'be37cb16-5207-bcd7-651d-10c4bb08003c';

  -- networking-basics / Network Safety and Basic Troubleshooting
  insert into public.learning_modules (id, course_id, title, description, position, published)
  values ('425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762', 'networking-basics', 'Network Safety and Basic Troubleshooting', 'How can users stay connected and safe? Wi-Fi protection and step-by-step troubleshooting.

You will learn to:
- Use basic Wi-Fi protections.
- Follow systematic steps to find common connectivity problems.
- Make safer choices on public Wi-Fi and with login pages.', 3, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('97e83b55-a14c-a208-2447-01d840a6b1cd', '425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762', 'Protecting access', 'article', 'Use a strong, unique Wi-Fi password and modern network protection such as **WPA2**-AES or WPA3 when supported. Avoid sharing the password publicly.

Install legitimate software **updates** when available.

A secure Wi-Fi link protects wireless access. Users should still check site authenticity and prefer **HTTPS** for sensitive browsing.', 0, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('7228705b-ed98-7fb7-22e8-f6a2dd4811f9', '425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762', 'Troubleshooting by scope', 'article', 'First observe the symptom: is one device affected, or everyone?

- Check airplane mode, the Wi-Fi network selected, signal strength, cabling and router power.
- Check whether the internet service is down.
- Compare another device on the same network.
- Test local access and internet access separately.
- Avoid changing many settings at once.', 1, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('a95a65de-cdde-6d7a-dc35-2048005a80fc', '425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762', 'Safer decisions', 'article', 'Unknown public Wi-Fi networks can pose risks, especially if a network is impersonating a trusted access point.

- Verify the network name with staff.
- Do not ignore security warnings.
- Use trusted services.
- Never share credentials just because a login page asks. Verify the page and the organization first.', 2, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('05b519f7-31da-2e51-6291-f8a9cd3fd67e', '425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762', 'Visual steps', 'steps', 'Start: only one device? | Ask whether one device is affected or everyone.
Yes: check the device | Look at its Wi-Fi setting, the network chosen, or its cable.
No: check the router or gateway | Look at router power and lights, then the internet service.
Change one thing at a time | Test after each change and note the result.
Do not reset yet | Do not reset until you understand what a reset will change.', 3, false);
  insert into public.learning_units (id, module_id, title, kind, content, position, published)
  values ('83fc5d5d-aa22-981e-6a64-db26959b0d45', '425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762', 'Example and practice', 'article', '### Example
A phone joins the Wi-Fi but cannot load pages. You test a second phone on the same network and it works. That points to the first phone, so you check its settings before touching the router.

### Practice
A phone connects to Wi-Fi but has no internet. Compare another phone, check the router indicators, verify the network, and write down which check narrowed down the cause.', 4, false);
  insert into public.learning_quizzes (id, module_id, title, pass_mark, published) values ('a4c7f05b-7c28-c202-28d7-5d66b68adf03', '425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762', 'Network Safety and Basic Troubleshooting: module quiz', 70, true);
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('4d46e876-485a-546e-4fd6-6a28bc429a77', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'Which is a recommended Wi-Fi security option when supported?', '["WPA3","No password","Open access for everyone","Posting the password publicly"]'::jsonb, 0, 0, 0, 1, 'WPA3 is a modern Wi-Fi security option.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('f379c3a4-65d2-2be4-9023-7cd6c56a42f6', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'What does troubleshooting mean?', '["Replacing every device immediately","Systematically identifying and resolving a problem","Turning off all security settings","Guessing passwords repeatedly"]'::jsonb, 1, 1, 0, 1, 'Troubleshooting is a structured process for narrowing down causes.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('a4788cbf-bd3b-8a25-7a81-bf57c6c978f8', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'What does HTTPS generally help protect?', '["A router from power failure","Every site from being fraudulent","Data exchanged with a website in transit","A computer from all malware"]'::jsonb, 2, 2, 0, 1, 'HTTPS encrypts web traffic in transit but does not guarantee a site is trustworthy.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('001da06f-08c6-bf5d-24fc-3f9eec6566c3', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'Why compare a second device on the same Wi-Fi network?', '["To improve screen resolution","To delete saved files","To increase modem size","To determine whether the issue is device-specific or network-wide"]'::jsonb, 3, 3, 1, 2, 'Comparison helps determine the likely scope of the fault.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('6938c070-016b-982a-7221-6977856a73c5', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'Why is a strong Wi-Fi password useful?', '["It reduces unauthorized access to the wireless network","It makes the internet free","It prevents every scam message","It guarantees perfect signal strength"]'::jsonb, 0, 4, 1, 2, 'Strong authentication helps restrict access to trusted users.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('59d90cdf-287a-0822-26b4-a9c74c3732fc', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'Why is a padlock icon not enough to prove a site is legitimate?', '["A padlock indicates no encryption","HTTPS encrypts the connection but scammers can also use HTTPS","All HTTPS sites are government sites","Wi-Fi must be switched off"]'::jsonb, 1, 5, 1, 2, 'Encryption and website legitimacy are different security questions.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('bb31cd8c-c7bd-9251-488c-9f25ea6c9367', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'A learner finds two similar Wi-Fi names in a cafe. What should they do?', '["Choose the one with the most suspicious login page","Use both at once","Ask staff to verify the official network before connecting","Share their password to test it"]'::jsonb, 2, 6, 2, 2, 'Verify the network name to reduce the risk of an impersonating hotspot.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('ccf6ed53-8a5c-5bc5-6aec-3637da5f8a22', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'Only one laptop cannot connect but all other devices can. What should be checked first?', '["The internet service for the entire country","Every other student''s passwords","Replace the provider network","The laptop''s Wi-Fi status, selected network, and saved settings"]'::jsonb, 3, 7, 2, 2, 'Begin by investigating the single affected device.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('539390a5-0f4b-c111-63cd-6f665888473a', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'A learner receives a browser warning about an invalid certificate. What is safest?', '["Do not bypass the warning for sensitive activity; verify the site and connection","Enter passwords anyway","Disable browser security permanently","Assume the warning is always a joke"]'::jsonb, 0, 8, 2, 2, 'Certificate errors require verification, especially before sharing sensitive information.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('e757ac11-b4d4-13c4-3764-f67fdde6c49c', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'All devices lose internet but can still print locally. What is the best initial diagnosis?', '["Every printer must be broken","Local LAN works; examine gateway or internet service","Every device has the same virus","Wi-Fi passwords must all be wrong"]'::jsonb, 1, 9, 3, 3, 'Local function plus widespread internet failure points upstream.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('e820b3a6-e94e-d802-ce80-56d67b59556f', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'A router restart does not restore access and the provider reports an outage. What should users do?', '["Keep changing random security settings","Factory-reset all devices immediately","Record the outage and use a trusted alternative if needed","Disable Wi-Fi encryption"]'::jsonb, 2, 10, 3, 3, 'An external service outage is not corrected by random local configuration changes.');
  insert into public.learning_quiz_questions (id, quiz_id, prompt, options, correct_index, position, competency, difficulty, explanation)
  values ('3b298bf5-4ec4-5349-d712-011e83a6e497', 'a4c7f05b-7c28-c202-28d7-5d66b68adf03', 'Which troubleshooting strategy produces the clearest evidence?', '["Change passwords, DNS, router, and cables simultaneously","Skip checking whether all devices are affected","Assume the first guess is correct","Test one variable at a time and note outcomes"]'::jsonb, 3, 11, 3, 3, 'Controlled checks help isolate causes and avoid introducing new faults.');
  insert into public.learning_activities (id, module_id, kind, title, prompt, spec, position, published)
  values ('b59b44f8-da71-d96e-b7e4-02a77ecea73f', '425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762', 'spot', 'Spot the risky settings', 'This is a router settings summary. Tap every risky setting, then press Check.', '{"segments":[{"id":"s1","text":"Wi-Fi name: CafeFree (open, no password)","flag":true,"why":"An open network has no encryption. Anyone nearby can join and watch unprotected traffic."},{"id":"s2","text":"Router admin password: admin","flag":true,"why":"A default admin password is widely known and lets others change your settings."},{"id":"s3","text":"Wi-Fi security: WPA3","flag":false,"why":"WPA3 is a strong, current security standard."},{"id":"s4","text":"Wi-Fi password: blue-mango-river-42","flag":false,"why":"A long, unique phrase is a good Wi-Fi password."},{"id":"s5","text":"Router software last updated 4 years ago","flag":true,"why":"Old firmware may contain known security holes. Keep it updated."},{"id":"s6","text":"Guest network turned on for visitors","flag":false,"why":"A guest network keeps visitors away from your own devices."}]}'::jsonb, 0, true);
  update public.learning_modules set published = true where id = '425e88d2-9ae0-3fd9-e4ad-bcbf5d1f6762';

  insert into public.glossary_terms (course_id, slug, term, definition, simple, example, category) values
    ('digital-literacy', 'hardware', 'hardware', 'The physical components of a computing device, such as the processor, memory, screen, and keyboard.', 'The parts of a device that you can touch.', 'The screen, battery, and camera of a phone.', 'Computers and Software'),
    ('digital-literacy', 'software', 'software', 'Programs and instructions that tell hardware what to do.', 'The apps and instructions that make a device useful.', 'A calculator app or a web browser.', 'Computers and Software'),
    ('digital-literacy', 'data', 'data', 'Information stored in a form a computer can process, such as text, numbers, images, or sound.', 'Facts and pictures that a device keeps and uses.', 'A photo, a saved contact, or a school grade.', 'Computers and Software'),
    ('digital-literacy', 'application', 'application', 'A software program designed to help a user perform a specific task.', 'An app: a tool on your device built to do one job.', 'A messaging app used to chat with a friend.', 'Computers and Software'),
    ('digital-literacy', 'internet', 'internet', 'A global system of interconnected networks that exchange data using shared communication rules.', 'A giant web of connected computers that lets you share information with people far away.', 'Opening a video call with a relative in another country.', 'Network Basics'),
    ('digital-literacy', 'network', 'network', 'A group of connected devices that can exchange data.', 'Devices that are linked so they can talk to each other.', 'The Wi-Fi in a home that connects a phone and a laptop.', 'Network Basics'),
    ('digital-literacy', 'browser', 'browser', 'Software used to retrieve, display, and navigate web pages.', 'The app that opens websites for you.', 'Chrome, Firefox, or Safari.', 'Computers and Software'),
    ('digital-literacy', 'password', 'password', 'A secret string of characters used to prove that you are allowed to access an account.', 'A secret word that proves you are really you.', 'A long phrase such as "blue-mango-river-42" used for one account only.', 'Security and Safety'),
    ('digital-literacy', 'authentication', 'authentication', 'The process of verifying a user identity before granting access.', 'Checking that you are who you say you are.', 'Typing a password and then a code sent to your phone.', 'Security and Safety'),
    ('digital-literacy', 'privacy', 'privacy', 'The ability to control what personal information is collected, shared, and who can see it.', 'Deciding who gets to know things about you.', 'Keeping your home address off public profiles.', 'Security and Safety'),
    ('digital-literacy', 'phishing', 'phishing', 'A form of social engineering in which attackers impersonate a trusted party to steal information.', 'A fake message that pretends to be someone you trust so you will give away secrets.', 'A text that claims to be your bank and asks for your PIN.', 'Security and Safety'),
    ('digital-literacy', 'scam', 'scam', 'A deceptive scheme intended to obtain money, goods, or information through false claims.', 'A trick used to get your money or your private details.', 'A message saying you won a prize but must pay a fee first.', 'Security and Safety'),
    ('digital-literacy', 'link', 'link', 'A clickable reference that opens another web page or file.', 'Something you tap that takes you to another page.', 'A web address inside a text message.', 'Internet Communication'),
    ('digital-literacy', 'malware', 'malware', 'Malicious software designed to damage, disrupt, or gain unauthorized access to a system.', 'A harmful program that sneaks onto a device.', 'A fake "free game" file that secretly steals saved passwords.', 'Security and Safety'),
    ('digital-literacy', 'email', 'email', 'A system for sending messages and files electronically between mailboxes over a network.', 'A letter that travels over the internet in seconds.', 'Sending homework to a teacher.', 'Internet Communication'),
    ('digital-literacy', 'attachment', 'attachment', 'A file sent together with an electronic message.', 'A file that rides along with your email.', 'A PDF assignment attached to an email.', 'Internet Communication'),
    ('digital-literacy', 'troubleshooting', 'troubleshooting', 'A systematic process of identifying the cause of a problem and testing fixes.', 'Finding out why something is not working and fixing it one step at a time.', 'Restarting a router and then checking whether a page loads.', 'Troubleshooting and Updates'),
    ('digital-literacy', 'update', 'update', 'A new version of software that adds features or fixes errors and security flaws.', 'A newer, better version of an app.', 'Installing a phone update that patches a security hole.', 'Troubleshooting and Updates'),
    ('digital-literacy', 'two-factor-authentication', 'two-factor authentication', 'A login method that requires two different proofs of identity, such as a password and a one-time code.', 'Using two locks instead of one on your account.', 'Entering your password and then a six-digit code from your phone.', 'Security and Safety'),
    ('digital-literacy', 'encryption', 'encryption', 'Converting data into an unreadable form that only someone with the correct key can reverse.', 'Scrambling a message so only the right person can unscramble it.', 'A messaging app that hides your chat from anyone who intercepts it.', 'Security and Safety'),
    ('networking-basics', 'lan', 'lan', 'Local Area Network: a network that covers a small area such as a home, school or office.', 'A small network that connects the devices that are close to each other.', 'The Wi-Fi network in your house that links your phone, laptop and printer.', 'Network Basics'),
    ('networking-basics', 'wan', 'wan', 'Wide Area Network: a network that connects LANs across a large geographic area, such as cities or countries.', 'A very big network that joins many smaller networks far apart.', 'A bank linking its branches in different cities.', 'Network Basics'),
    ('networking-basics', 'router', 'router', 'A device that forwards data between networks and connects a local network to the internet.', 'The traffic director of your home network: it decides where data should go.', 'The box that gives your phone and laptop their Wi-Fi and internet access.', 'Devices and Connections'),
    ('networking-basics', 'modem', 'modem', 'A device that converts the signal from your internet provider into data your network can use, and back again.', 'The doorway between your home and your internet company.', 'The box connected to the fiber, cable or phone line coming into the house.', 'Devices and Connections'),
    ('networking-basics', 'switch', 'switch', 'A device that connects several wired devices on a LAN and sends data only to the device it is meant for.', 'A smart power strip for network cables that sends each message to the right computer.', 'The box in a school lab that connects 24 desktop computers.', 'Devices and Connections'),
    ('networking-basics', 'ethernet', 'ethernet', 'A standard for wired network connections using cables, usually fast and stable.', 'A network cable that plugs into a computer.', 'A cable between a desktop computer and the router.', 'Devices and Connections'),
    ('networking-basics', 'wi-fi', 'wi-fi', 'A wireless technology that connects devices to a network using radio waves.', 'A way to connect to the network without a cable.', 'Connecting your phone to the home network in the living room.', 'Devices and Connections'),
    ('networking-basics', 'ip-address', 'ip address', 'A number that identifies a device on a network so data can be delivered to it.', 'The home address of a device on a network.', '192.168.1.10 is a typical address of a device on a home network.', 'Internet Communication'),
    ('networking-basics', 'dns', 'dns', 'Domain Name System: a service that translates website names into IP addresses.', 'The phone book of the internet: you give it a name and it gives back the number.', 'Turning example.com into the address your browser can connect to.', 'Internet Communication'),
    ('networking-basics', 'packet', 'packet', 'A small piece of data sent across a network, with information about where it comes from and where it goes.', 'A tiny envelope of data. Big messages are split into many envelopes.', 'A photo sent to a friend is cut into many packets and put back together on arrival.', 'Internet Communication'),
    ('networking-basics', 'server', 'server', 'A computer that provides pages, files or services to other devices.', 'A computer that answers when other computers ask for something.', 'The computer that sends you a web page when your browser asks for it.', 'Network Basics'),
    ('networking-basics', 'isp', 'isp', 'Internet Service Provider: a company that gives you access to the internet.', 'The company you pay to get internet at home.', 'A telephone or fiber company that sells home internet.', 'Network Basics'),
    ('networking-basics', 'wpa2', 'wpa2', 'A common Wi-Fi security standard that encrypts traffic between your device and the router. WPA3 is newer and stronger.', 'A secret lock on your Wi-Fi so that strangers cannot read your messages.', 'Choosing WPA2 or WPA3 in your router settings instead of leaving Wi-Fi open.', 'Security and Safety'),
    ('networking-basics', 'access-point', 'access point', 'A device that lets Wi-Fi capable devices join a wired network (LAN) wirelessly.', 'The spot that sends out the Wi-Fi signal so your phone can join the network.', 'A ceiling-mounted Wi-Fi unit in a school corridor.', 'Devices and Connections'),
    ('networking-basics', 'gateway', 'gateway', 'A device that connects a local network to other networks, such as the internet, and forwards traffic between them.', 'The door that your home network uses to reach the outside world.', 'A provider box that works as modem and router together.', 'Devices and Connections'),
    ('networking-basics', 'https', 'https', 'HyperText Transfer Protocol Secure: web communication that is encrypted while it travels.', 'A locked way of talking to a website so people along the way cannot read your messages.', 'The padlock in the address bar when you log in to a website. It protects the connection but does not prove the site is honest.', 'Security and Safety'),
    ('networking-basics', 'network', 'network', 'A group of connected devices that can exchange data.', 'Devices that are linked so they can talk to each other.', 'The Wi-Fi in a home that connects a phone and a laptop.', 'Network Basics'),
    ('networking-basics', 'internet', 'internet', 'A global system of interconnected networks that exchange data using shared communication rules.', 'A giant web of connected computers that lets you share information with people far away.', 'Opening a video call with a relative in another country.', 'Network Basics'),
    ('networking-basics', 'troubleshooting', 'troubleshooting', 'A systematic process of identifying the cause of a problem and testing fixes.', 'Finding out why something is not working and fixing it one step at a time.', 'Restarting a router and then checking whether a page loads.', 'Troubleshooting and Updates'),
    ('networking-basics', 'phishing', 'phishing', 'A form of social engineering in which attackers impersonate a trusted party to steal information.', 'A fake message that pretends to be someone you trust so you will give away secrets.', 'A text that claims to be your bank and asks for your PIN.', 'Security and Safety'),
